# Focused Stage 1 checks. Offline; no historical runner is sourced.
source('R/audit_mcp_coverage.R')
checks <- 0L
check <- function(x,label){checks<<-checks+1L;if(!isTRUE(x))stop(label,call.=FALSE)}
fails <- function(expr)inherits(tryCatch({force(expr);NULL},error=identity),'error')
allowed <- c('R/audit_mcp_coverage.R','R/test_mcp_coverage.R','docs/action-factor-definition-and-coverage.md','data/manifests/mcp-source-files.csv','PROJECT_CONTEXT.md','docs/status.md','docs/data-source-contract.md')
historical <- setdiff(c(system2('git',c('ls-files'),stdout=TRUE),list.files('data/raw',recursive=TRUE,full.names=TRUE),list.files('data/pilot',recursive=TRUE,full.names=TRUE)),allowed)
historical <- historical[!grepl('/mcp-stage1-',historical)&file.exists(historical)]
before <- vapply(historical,mcp_sha,'')
m <- mcp_verify();check(nrow(m)==11L,'Exact source scope')
tree <- jsonlite::fromJSON('data/raw/reference/mcp-stage1-source-tree.json')
check(!tree$truncated,'Untruncated revision tree')
for(j in seq_len(nrow(m))){i<-match(m$source_path[j],tree$tree$path);check(!is.na(i)&&tree$tree$sha[i]==m$git_blob[j]&&tree$tree$size[i]==as.numeric(m$bytes[j]),'Tree provenance');check(m$sha256[j]==mcp_source_pins[[m$source_path[j]]],'Declared SHA');check(grepl(mcp_revision,m$raw_url[j],fixed=TRUE)&&grepl(mcp_revision,m$metadata_url[j],fixed=TRUE),'Revision URLs')}
f<-tempfile();writeLines('unlicensed fixture',f);check(fails(mcp_rights(f)),'Rights fail closed');check(fails(mcp_verify_file(f,1,'bad')),'Size failure');check(fails(mcp_verify_file(f,file.info(f)$size,'bad')),'Blob failure');check(fails(mcp_verify_file(f,file.info(f)$size,mcp_blob(f),'bad')),'SHA failure');unlink(f)
check(identical(mcp_date_valid(c('20240229','20230229','20241301','2024','RR')),c(TRUE,FALSE,FALSE,FALSE,FALSE)),'Calendar dates')
raw<-mcp_read('data/raw/reference/mcp-stage1-charting-m-matches.csv');a<-raw[1:6,];a$match_id<-paste0('20240101-fixture-',1:6);a$Date<-'20240101';a$Surface<-'Hard';a[['Best of']]<-'3';a[['Player 1']]<-'Alpha';a[['Player 2']]<-'Beta';a$Round<-c('F','Q1','F','RR','R32','F');a$Tournament<-c('Australian_Open','Australian_Open','Irving CH','Davis Cup','Doha','Wimbedon');b<-mcp_metadata(a,'ATP')
check(identical(b$scope,c('MAJOR_MAIN_DRAW_LABEL_SUPPORTED','NOT_MAIN_DRAW_ROUND_OR_UNKNOWN','LOWER_LEVEL_OR_JUNIOR_LABEL','TEAM_EXHIBITION_OR_OTHER_REVIEW','OTHER_MAIN_DRAW_TOUR_LEVEL_UNVERIFIED','OTHER_MAIN_DRAW_TOUR_LEVEL_UNVERIFIED')),'Scope does not invent tour classification or repair spelling')
a[['Player 1']]<-'Beta';a[['Player 2']]<-'Alpha';bb<-mcp_metadata(a,'ATP');check(identical(b$player_a,bb$player_a)&&identical(b$player_b,bb$player_b),'Outcome-neutral slots')
a$match_id[2]<-a$match_id[1];check(all(mcp_metadata(a,'ATP')$duplicate_id[1:2]),'Both duplicate metadata rows flagged')
check(fails(mcp_metadata(raw[-1],'ATP')),'Schema failure')
l<-mcp_lexical(c('4*','6#','6f#','6s17f1*','4+b27v1*','6n','R','4f2b3n@','4q9f*'),c('','','','','','5d','','',''))
check(identical(which(l$plus1_prefix_present),c(4L,5L,8L,9L)),'Plus-one lexical cases')
check(all(l$serve_terminal_candidate[1:2])&&l$return_terminal_candidate[3],'Serve versus return terminal')
check(l$plus1_terminal_winner_candidate[4]&&l$plus1_terminal_error_candidate[8],'Plus-one terminal candidates')
check(l$outcome_only_or_penalty[7]&&l$unknown_code[9],'Unknown/outcome-only not hidden')
check(!l$plus1_prefix_present[6]&&!l$return_prefix_present[6],'Second serve selected; no invented return')
check(l$return_depth_recorded[4]&&l$return_direction_recorded[4]&&l$plus1_direction_recorded[5],'Recorded directions and depth')
z<-data.frame(Pts='40-15',Svr='1',PtWinner='1',Gm1='5',Gm2='3',Set1='1',Set2='0')
check(mcp_terminal(z,'3')=='ORDINARY_TERMINAL_SCORE_PATTERN','Ordinary terminal arithmetic')
z2<-z;z2$Svr<-'2';z2$PtWinner<-'2';z2$Gm1<-'3';z2$Gm2<-'5';z2$Set1<-'0';z2$Set2<-'1';check(mcp_terminal(z2,'3')==mcp_terminal(z,'3'),'Terminal player relabeling')
z$Pts<-'6-5';check(mcp_terminal(z,'3')=='UNRESOLVED','Tiebreak is not silently interpreted');z$Pts<-'30-15';check(mcp_terminal(z,'3')=='UNRESOLVED','Partial ending')
z$Pts<-'40-15';z$Set1<-'0';check(mcp_terminal(z,'3')=='UNRESOLVED','Nonfinal set')
fixture<-as.data.frame(setNames(rep(list(rep('',2)),14),c('match_id','Pt','Set1','Set2','Gm1','Gm2','Pts','Gm#','TbSet','Svr','1st','2nd','Notes','PtWinner')),check.names=FALSE)
fixture$match_id<-'orphan';fixture$Pt<-'1';fixture$Svr<-'1';fixture$PtWinner<-'2';fixture[['1st']]<-'6f*';fixture$Notes[1]<-'retired';q<-mcp_point_summary(fixture,'fixture',b)
check(q$summary$orphan_point_rows==2&&q$summary$duplicate_point_rows==2,'Orphan and duplicate accounting');check(q$matches$status_note_cues==1&&!q$matches$point_sequence_contiguous,'Status cue and sequence conflict');check(q$matches$terminal_evidence=='UNRESOLVED','No metadata means unknown completion')
cat('Fixtures and input pins passed; running independent full audit.\n')
r<-mcp_build();paths<-paste0(mcp_prefix,mcp_outputs,'.csv')
for(j in seq_along(r)){f<-tempfile();mcp_write(r[[j]],f);check(mcp_sha(f)==mcp_sha(paths[j]),paste('Byte-identical',mcp_outputs[j]));unlink(f)}
x<-r[[1]];cv<-r[[2]];fields<-r[[3]];sample<-r[[4]];s<-r[[5]]
check(nrow(x)==11830&&sum(x$tour_file=='ATP')==7566&&sum(x$tour_file=='WTA')==4264,'Every metadata row retained')
check(sum(s$rows)==1877757&&sum(s$orphan_point_rows)==0,'Every source point accounted')
check(sum(s$duplicate_point_rows)==5250&&sum(s$duplicate_entire_rows)==2129,'Duplicate accounting')
check(sum(x$point_files==0)==37&&sum(x$point_files>1)==0,'Missing and cross-shard linkage')
check(sum(x$duplicate_id)==16&&sum(x$bad_point_owner,na.rm=TRUE)==0,'Identity ambiguity and point owners')
for(t in c('ATP','WTA')){y<-x[x$tour_file==t,];check(length(unique(y$match_id[y$point_files>0]))==sum(s$unique_matches[grepl(if(t=='ATP')'-m-' else '-w-',s$point_file)]),'Point match linkage equality')}
for(level in c('overall','tour','year','event','surface','cell'))check(sum(cv$metadata_rows[cv$level==level])==nrow(x),paste('Partition',level))
check(nrow(fields)==84&&all(fields$nonblank<=fields$rows),'Field coverage');check(!any(c('isAce','isDouble','rallyCount','TB?','Ret') %in% fields$field),'Derived dictionary fields absent in actual export')
check(nrow(sample)==44&&sum(sample$tour_file=='ATP')==20&&sum(sample$tour_file=='WTA')==24,'Prototype strata')
check(all(x$metadata_ok[match(sample$match_id,x$match_id)])&&all(x$scope[match(sample$match_id,x$match_id)]=='MAJOR_MAIN_DRAW_LABEL_SUPPORTED'),'Proposed sample frame')
# Smaller fixed eligible candidate pool tests ranking; the full independent run tests all candidates.
u<-x[match(sample$match_id,x$match_id),];sa<-mcp_sample(u);u$irrelevant_winner<-rev(seq_len(nrow(u)));u$irrelevant_performance<-999;sb<-mcp_sample(u[nrow(u):1,]);check(identical(sa,sb),'Sampling ignores outcomes/performance and row order')
u2<-u;u2$player1<-u$player2;u2$player2<-u$player1;check(identical(mcp_sample(u2),sa),'Sampling neutral to source player-slot order')
check(!anyDuplicated(sample$sampling_hash)&&!anyDuplicated(sample$match_id),'Sample unique identities')
check(all(x$completion[x$duplicate_id|x$point_files!=1]=='UNRESOLVED'),'Conflicted linkage cannot certify completion')
check(all(s$plus1_direction_recorded<=s$plus1_prefix_present)&&all(s$plus1_prefix_present<=s$return_prefix_present),'Lexical nesting')
check(setequal(system2('git',c('check-ignore','--',paths),stdout=TRUE),paths),'Ignored output scope')
check(setequal(list.files('data/pilot',pattern='^mcp-stage1-',full.names=TRUE),paths),'Exactly five outputs')
old<-vapply(paths,mcp_sha,'');mcp_install(r);check(identical(old,vapply(paths,mcp_sha,'')),'Idempotent installation')
wrong<-r;wrong[[1]]$match_id[1]<-'do-not-install';check(fails(mcp_install(wrong)),'Differing release refused');check(identical(old,vapply(paths,mcp_sha,'')),'Rejected install leaves all outputs intact')
check(!length(list.files('data/pilot',pattern='^\\.mcp-',all.files=TRUE)),'No staging residue')
check(identical(before,vapply(historical,mcp_sha,'')),'Historical artifacts unchanged during checks')
changed<-system2('git',c('diff','HEAD','--name-only'),stdout=TRUE);untracked<-system2('git',c('ls-files','--others','--exclude-standard'),stdout=TRUE)
changed<-unique(c(changed,untracked))
check(all(file.exists(allowed))&&(!length(changed)||setequal(changed,allowed)),'Exact seven-file tracked scope, including staged changes')
cat(sprintf('PASS: %d focused checks; %d historical files unchanged; five independent byte-identical outputs.\n',checks,length(historical)))
